        int left = 1, right = *max_element(piles.begin(), piles.end());
        while (left < right) {
            int mid = left + right >> 1;
            int s = 0;
            for (int pile : piles) s += (pile + mid - 1) / mid;
            if (s <= h)
                right = mid;
            else
                left = mid + 1;
        }
        return left;
    }
